insert into assignments (class_id, title, description, due_date) select '1d', 'Il mio archivio digitale', 'Sul PC di casa o in Google Drive crea la cartella Scuola con una sottocartella per ogni materia e salvaci dentro almeno tre file con nomi nel formato AAAA-MM-GG_materia_cognome_contenuto. Fai uno screenshot della struttura con le estensioni visibili e consegnalo come immagine PNG o JPG. Nel campo nota scrivi in due righe quale regola userai per non perdere più i file.', '2026-10-16' where not exists (select 1 from assignments where class_id = '1d' and title = 'Il mio archivio digitale');
insert into assignments (class_id, title, description, due_date) select '1d', 'Allenamento sulle conversioni', 'Scarica conversioni.xlsx dai materiali. Converti a mano 5 numeri decimali a scelta tra 20 e 250 (tabella delle divisioni) e 5 numeri binari a 8 bit (somma dei pesi), poi controlla i risultati in Calc con DECIMALE.BINARIO e BINARIO.DECIMALE. Consegna il file chiamato conversioni-cognome.ods.', '2026-10-23' where not exists (select 1 from assignments where class_id = '1d' and title = 'Allenamento sulle conversioni');
insert into assignments (class_id, title, description, due_date) select '1e', 'Il mio archivio digitale', 'Sul PC di casa o in Google Drive crea la cartella Scuola con una sottocartella per ogni materia e salvaci dentro almeno tre file con nomi nel formato AAAA-MM-GG_materia_cognome_contenuto. Fai uno screenshot della struttura con le estensioni visibili e consegnalo come immagine PNG o JPG. Nel campo nota scrivi in due righe quale regola userai per non perdere più i file.', '2026-10-16' where not exists (select 1 from assignments where class_id = '1e' and title = 'Il mio archivio digitale');
insert into assignments (class_id, title, description, due_date) select '1e', 'Allenamento sulle conversioni', 'Scarica conversioni.xlsx dai materiali. Converti a mano 5 numeri decimali a scelta tra 20 e 250 (tabella delle divisioni) e 5 numeri binari a 8 bit (somma dei pesi), poi controlla i risultati in Calc con DECIMALE.BINARIO e BINARIO.DECIMALE. Consegna il file chiamato conversioni-cognome.ods.', '2026-10-23' where not exists (select 1 from assignments where class_id = '1e' and title = 'Allenamento sulle conversioni');
insert into assignments (class_id, title, description, due_date) select '3g', 'Un convertitore in Calc', 'Costruisci in Calc un convertitore: scrivi un numero decimale tra 0 e 255 in una cella e ottieni il binario a 8 bit con la tabella delle divisioni (QUOZIENTE e RESTO). Aggiungi una cella di verifica con DECIMALE.BINARIO e fai comparire "Fuori intervallo" se il numero è minore di 0 o maggiore di 255. Consegna il file convertitore-cognome.ods.', '2026-10-20' where not exists (select 1 from assignments where class_id = '3g' and title = 'Un convertitore in Calc');
insert into assignments (class_id, title, description, due_date) select '5f', 'Progetto e operazione nella mia impresa', 'Descrivi l''impresa del tuo PCTO, o un''altra impresa reale: forma giuridica, classe dimensionale UE (con i dati e la fonte) e almeno 4 stakeholder con il loro interesse. Individua poi un progetto e un''attività operativa di quell''impresa e spiega in 3–4 righe perché li classifichi così. Consegna in PDF.', '2026-10-21' where not exists (select 1 from assignments where class_id = '5f' and title = 'Progetto e operazione nella mia impresa');
insert into assignments (class_id, title, description, due_date) select '5f', 'Organigramma ragionato', 'Cerca l''organigramma di un''impresa o di un ente reale (sul suo sito o nella sezione Amministrazione trasparente di un ente pubblico) e ridisegnalo in draw.io. Aggiungi un paragrafo di 5–6 righe: che struttura è, che autorità avrebbe un project manager, un pro e un contro per quell''organizzazione. Consegna immagine e testo in un unico PDF.', '2026-10-28' where not exists (select 1 from assignments where class_id = '5f' and title = 'Organigramma ragionato');
insert into assignments (class_id, title, description, due_date) select '5g', 'Startup Lab: backlog e sprint plan', 'Completate il backlog del team fino ad almeno 10 user story, ognuna con criteri di accettazione, stima in story point e priorità. Scrivete poi lo sprint plan del prossimo giorno di laboratorio: obiettivo dello sprint in una frase, storie scelte entro la capacità del team, attività per ogni storia e Definition of Done. Consegnate il file backlog-nomestartup.ods con il link alla board Kanban nella nota.', '2026-10-22' where not exists (select 1 from assignments where class_id = '5g' and title = 'Startup Lab: backlog e sprint plan');
insert into assignments (class_id, title, description, due_date) select '5g', 'Audit della mia sicurezza digitale', 'Scegli tre tuoi account (per esempio posta, social, gioco) e per ciascuno verifica se la password è unica, se è attiva la verifica in due passaggi e quali dispositivi risultano collegati. Non scrivere mai le password. In una tabella di Calc riporta i problemi trovati, la contromisura e se l''hai già applicata, più tre righe di riflessione. Consegna audit-cognome.ods.', '2026-10-29' where not exists (select 1 from assignments where class_id = '5g' and title = 'Audit della mia sicurezza digitale');
