-- Programma svolto: un argomento per riga, con i materiali collegati
create table if not exists topics (
  id           uuid primary key default gen_random_uuid(),
  class_id     text not null references classes on delete cascade,
  position     int  not null default 0,
  title        text not null check (char_length(title) between 1 and 200),
  description  text check (char_length(description) <= 2000),
  done         boolean not null default true,
  material_ids uuid[] not null default '{}',
  created_at   timestamptz not null default now()
);
create index if not exists topics_class_pos on topics (class_id, position);
alter table topics enable row level security;
grant select on topics to anon, authenticated;
grant insert, update, delete on topics to authenticated;
drop policy if exists "topics read" on topics;
drop policy if exists "topics write" on topics;
create policy "topics read"  on topics for select using (true);
create policy "topics write" on topics for all using (current_user_is_teacher()) with check (current_user_is_teacher());

